struct RigidBody
{
    BodyID ID;
    bool Active;

    BodyType Type;

    MotionState State;
    MassProperties Mass;
    ForceAccumulation Forces;

    bool EnableGravity;
    float GravityScale;

    float LinearDamping;
    float AngularDamping;

    float MaxLinearSpeed;
    float MaxAngularSpeed;

    CollisionDetectionMode CollisionDetection;

    bool AllowSleeping;
    bool Sleeping;
    float SleepTimer;
};

struct MotionState
{
    Vec3f Position;
    Quaternionf Rotation;

    Vec3f LinearVelocity;
    Vec3f AngularVelocity;
};

struct ForceAccumulation
{
    Vec3f Force;
    Vec3f Torque;
};

bool Sleeping;
float SleepTimer;
bool AllowSleeping;

enum class BodyType
{
    Static,
    Kinematic,
    Dynamic
};

