Quaternionf IntegrateAngularVelocityExpMap(
    const Quaternionf& orientation,
    const Vec3f& angularVelocity,
    float dt)
{
    const float speed =
        angularVelocity.Length();

    // Small-angle branch avoids division by a tiny speed.
    if (speed < 1.0e-7f)
    {
        const Quaternionf omega{
            angularVelocity,
            0.0f
        };

        return (
            orientation +
            omega *
            orientation *
            (0.5f * dt)
        ).Normalized();
    }

    const Vec3f axis =
        angularVelocity /
        speed;

    const float angle =
        speed * dt;

    const float half =
        0.5f * angle;

    const float s =
        std::sin(half);

    const Quaternionf delta{
        axis * s,
        std::cos(half)
    };

    // World-space angular velocity convention.
    return (
        delta *
        orientation
    ).Normalized();
}

