struct PoseHistory
{
    Transformf Previous;
    Transformf Current;
};

void SetKinematicTarget(
    BodyID body,
    const Vec3f& targetPosition,
    const Quaternionf& targetRotation,
    float fixedDt)
{
    RigidBody& b =
        RequireBody(body);

    if (b.Type != BodyType::Kinematic)
        throw ...;

    // Linear velocity that reaches target exactly at the
    // end of the next fixed simulation step.
    b.State.LinearVelocity =
        (
            targetPosition -
            b.State.Position
        ) / fixedDt;

    // Relative finite rotation.
    Quaternionf delta =
        targetRotation *
        b.State.Rotation.Conjugate();

    // q and -q represent the same orientation.
    // Flip to use the shortest angular route.
    if (delta.w < 0.0f)
        delta = -delta;

    delta =
        delta.Normalized();

    const float sinHalf =
        Vec3f{
            delta.x,
            delta.y,
            delta.z
        }.Length();

    if (sinHalf < 1.0e-7f)
    {
        b.State.AngularVelocity =
            Vec3f::Zero();
    }
    else
    {
        const Vec3f axis =
            Vec3f{
                delta.x,
                delta.y,
                delta.z
            } /
            sinHalf;

        const float angle =
            2.0f *
            std::atan2(
                sinHalf,
                delta.w);

        b.State.AngularVelocity =
            axis *
            (angle / fixedDt);
    }
}

if (!IsDynamicBodyType(record))
{
